import{_ as i,a as s,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"Go 编码规范：格式、命名、接口与评审","description":"融合导入、命名、注释、声明和项目结构规则，区分 Go 惯例与团队选择。","frontmatter":{"title":"Go 编码规范：格式、命名、接口与评审","description":"融合导入、命名、注释、声明和项目结构规则，区分 Go 惯例与团队选择。","sources":[{"repository":"jekyall_blog","file":"_posts/Language/golang/代码规范/coding_guidelines.md"}],"showdocs":{"topics":[{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"开发实践","scope":"general","audience":"general","group":"语言与开发","summary":"融合导入、命名、注释、声明和项目结构规则，区分 Go 惯例与团队选择。","status":"active","related":[{"title":"Beego 工程维护：模块、MVC 与排错","link":"/programming/go/plus/ecosystem/base-beego","kind":"开发实践","scope":"general","audience":"general"},{"title":"Gin 与 SQLite · 运行、重启与失败测试","link":"/programming/go/plus/practice/api-part-02","kind":"知识专题","scope":"general","audience":"general"},{"title":"Gin 与 SQLite · 状态机、事务与接口契约","link":"/programming/go/plus/practice/api-part-01","kind":"知识专题","scope":"general","audience":"general"},{"title":"Go 包与模块：导入、导出与依赖方向","link":"/programming/go/base/intermediate/engineering","kind":"知识专题","scope":"general","audience":"general"},{"title":"Go 变量、类型与控制流","link":"/programming/go/base/basic/values","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"Go 测试：断言、隔离与失败定位","link":"/programming/go/testing"},"next":{"text":"Go 文件与 I/O：短读、字节流和资源所有权","link":"/programming/go/plus/stdlib/stdlib"}},"hashRedirects":{"代码指导":"/programming/go/plus/practice/coding_guidelines#format-and-names","基本约束":"/programming/go/plus/practice/coding_guidelines#format-and-names"},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Go 测试：断言、隔离与失败定位","link":"/programming/go/testing"},"next":{"text":"Go 文件与 I/O：短读、字节流和资源所有权","link":"/programming/go/plus/stdlib/stdlib"}},"headers":[],"relativePath":"programming/go/plus/practice/coding_guidelines.md","filePath":"programming/go/plus/practice/coding_guidelines.md"}'),n={name:"programming/go/plus/practice/coding_guidelines.md"};function o(r,e,l,p,d,h){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="go-编码规范-格式、命名、接口与评审" tabindex="-1">Go 编码规范：格式、命名、接口与评审 <a class="header-anchor" href="#go-编码规范-格式、命名、接口与评审" aria-label="Permalink to &quot;Go 编码规范：格式、命名、接口与评审&quot;">​</a></h1><p><span id="代码指导"></span><span id="基本约束"></span></p><p>先遵循项目已有约定，再用以下规则评审可读性、接口与验证方式。Go 工具和官方惯例提供共同基础，团队自己的版本号、行宽、测试框架和覆盖率要求应在贡献指南里明确。</p><h2 id="format-and-names" tabindex="-1">格式、命名与声明 <a class="header-anchor" href="#format-and-names" aria-label="Permalink to &quot;格式、命名与声明 {#format-and-names}&quot;">​</a></h2><ul><li>使用 <code>gofmt</code>，导入排序由工具处理；行宽按可读性和团队约定判断，不手动与工具争夺格式。</li><li>包名简短、小写并有明确含义，调用处无需重复包名，例如 <code>user.Service</code> 通常比 <code>user.UserService</code> 更清楚。局部变量名可短，跨越较长作用域的名字应表达用途。</li><li>导出标识符首字母大写；<code>userID</code>、<code>HTTPClient</code> 等首字母缩写保持惯用大小写。常量通常使用 <code>MaxRetries</code>、<code>maxRetries</code>，全大写下划线不是 Go 的通用惯例。</li><li>布尔名称表达状态即可，例如 <code>ready</code>、<code>enabled</code>，不必全部加 Is/Has。接口按能力命名，如 <code>Reader</code>；不要预先把实现的全部方法搬进大接口。</li><li>参数按逻辑关系排列；需要 context 时通常把 <code>ctx context.Context</code> 放在第一位，<code>error</code> 放在结果最后。相邻同类型参数可以合写，多个同型字符串容易误传时应重新考虑 API。</li></ul><h2 id="imports" tabindex="-1">导入与包依赖 <a class="header-anchor" href="#imports" aria-label="Permalink to &quot;导入与包依赖 {#imports}&quot;">​</a></h2><p>标准库与其他导入通常用空行分组，是否将组织内部包再分组由项目决定。导入路径是模块路径加包的相对路径，不需要真的能被浏览器直接打开。Modules 工程不使用 <code>./subpackage</code> 导入。</p><p>避免点导入，必要的别名应解释冲突或用途。空白导入 <code>_</code> 用于显式依赖初始化副作用，例如某些 SQL 驱动；普通未使用依赖应删除，不以空白导入掩盖。工具安装和模块依赖更新见<a href="/programming/go/modules#part-1-dependency-workflow">模块管理</a>。</p><h2 id="comments" tabindex="-1">注释与文档 <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;注释与文档 {#comments}&quot;">​</a></h2><p>导出的类型、函数、常量组和包应说明用途与约束，文档注释通常以标识符名称开头，并写成完整句子。注释解释业务限制、生命周期、并发安全和错误语义，不逐行翻译实现。较长包说明可以放在 <code>doc.go</code>。</p><div class="language-go vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Reader reads records from a stream. It is not safe for concurrent use.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Reader</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> interface</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    ReadRecord</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>此处 <code>Record</code> 代表业务类型，是接口设计片段。可执行示例放入 <code>example_test.go</code>，用 Output 注释让 <code>go test</code> 验证。TODO/FIXME 要有具体未完成事项，必要时关联问题编号。</p><h2 id="code-review" tabindex="-1">控制流、错误与数据 <a class="header-anchor" href="#code-review" aria-label="Permalink to &quot;控制流、错误与数据 {#code-review}&quot;">​</a></h2><p>优先提前返回，保持正常路径清楚；失败要添加足够的操作上下文并保留错误链。不要忽略读取、解析和数据库操作的错误。资源成功取得后再 defer 释放；为阻塞操作提供超时与取消，并确认 goroutine 何时返回。</p><p>结构体用带字段名的字面量初始化。接收者要匹配修改语义、方法集和复制限制，包含锁的对象尤其不能在使用后复制。共享 map 或切片的所有权应明确。函数摆放顺序以相关定义易查为准，不强制全部项目遵守 CRUD 顺序或插入大段字符画。</p><h2 id="ownership" tabindex="-1">边界复制与公开接口 <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;边界复制与公开接口 {#ownership}&quot;">​</a></h2><p>接收并长期保存外部 slice/map，或返回内部集合时，明确调用方是否可修改。需要独立所有权就复制；含指针的元素仍是浅复制。可用 slices.Clone、maps.Clone 或显式遍历，但不能将复制当作并发同步手段。不要无意通过嵌入类型暴露其全部方法，API 只公开使用方需要的能力。</p><p>接口通常按值传递，底层对象可以是指针。编译期可用局部片段 <code>var _ Finisher = (*Task)(nil)</code> 检查实现关系，前提是 Finisher 与 Task 已按接口章节定义；不需要给接口变量再加一层指针来修改对象。</p><h2 id="team-choices" tabindex="-1">团队约定与语言保证 <a class="header-anchor" href="#team-choices" aria-label="Permalink to &quot;团队约定与语言保证 {#team-choices}&quot;">​</a></h2><p>旧 Uber 译本中“枚举从1开始”“channel容量只能是0或1”“包级私有变量加下划线”等是团队选择，不是语言限制。根据零值含义设计枚举，根据背压与所有权设计通道容量。当前标准库已有类型化 atomic 值，不能把额外原子库说成唯一类型安全方案。</p><p>避免可变全局状态，优先构造函数传入依赖；init 用于确有必要的初始化，不把复杂网络连接藏进去。nil slice 与空 slice 在 JSON 等边界可能不同，应按契约决定。不要遮蔽 nil、len 等预声明名称；原始字符串可简化多行文本，但仍需理解其中的换行。</p><p>功能选项适合逐步扩展可选配置的 API，选项要验证范围、冲突和默认值。普通参数已经清楚时不增加模式。性能方面，容量提示、strconv 或减少转换只在实际负载和基准支持下采用，不承诺绝对更快。</p><p>业务函数返回 error，main 统一决定退出码；os.Exit 和 log.Fatal 会跳过尚未执行的 defer，不宜在库函数中随意退出进程。</p><h2 id="project-structure" tabindex="-1">项目结构与版本 <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;项目结构与版本 {#project-structure}&quot;">​</a></h2><p>Go 没有适用于所有应用的强制目录模板。小程序可先保持单一 main 包；有多个可执行入口时可用 <code>cmd/&lt;name&gt;</code>，需要限制模块外部导入的实现放 <code>internal</code>。按实际职责拆包，避免为了目录齐全建立空的 models/service/repository。</p><p>示意结构：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>go.mod</span></span>
<span class="line"><span>cmd/server/main.go</span></span>
<span class="line"><span>internal/user/</span></span>
<span class="line"><span>internal/storage/</span></span></code></pre></div><p>配置、模板、静态资源按应用需要加入；运行日志和临时数据通常不是源码结构的一部分。版本表达由发布流程决定，不要求所有 main 包包含 APP_VER，也不要求库实现 Version 函数。</p><h2 id="tests" tabindex="-1">测试与验收 <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;测试与验收 {#tests}&quot;">​</a></h2><p>测试文件使用 <code>_test.go</code>，函数遵循 <code>TestXxx</code>、<code>BenchmarkXxx</code> 等约定。优先覆盖正常输入、失败分支、边界值和外部契约；覆盖率阈值由风险与项目要求决定。修复缺陷先复现，再确认测试能够捕获回归。<a href="/programming/go/testing#part-1-example">测试课程</a>提供可运行的表格测试、示例和基准。</p><p>常规验证：<code>go fmt ./...</code>、<code>go vet ./...</code>、<code>go test ./...</code>；涉及共享数据时在支持的平台增加 <code>go test -race ./...</code>。</p><h2 id="sources" tabindex="-1">进一步阅读 <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;进一步阅读 {#sources}&quot;">​</a></h2><p>团队的具体约定可以写在项目贡献指南中。参考 <a href="https://go.dev/wiki/CodeReviewComments" target="_blank" rel="noopener noreferrer">Go Code Review Comments</a>、<a href="https://go.dev/doc/effective_go" target="_blank" rel="noopener noreferrer">Effective Go</a> 与 <a href="https://go.dev/doc/modules/layout" target="_blank" rel="noopener noreferrer">组织模块文档</a>。许可证应以项目 LICENSE 和实际采用的条款为准，不从源文件头部模板推断授权。</p><h2 id="static-review" tabindex="-1">评审练习与参考答案 <a class="header-anchor" href="#static-review" aria-label="Permalink to &quot;评审练习与参考答案 {#static-review}&quot;">​</a></h2><p>假设调用方要得到一份可以自行修改的记录列表。先预测哪一行会改到仓库内部的标题，再对照结果。</p><div class="language-go vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Record</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ Title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stored </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> []</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{Title: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;初稿&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">view </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> append</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), stored</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">view[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].Title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;修订&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       // stored[0].Title 也变为“修订”</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">view[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{Title: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;另写&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// stored[0] 仍指向“修订”</span></span></code></pre></div><p>切片复制创建了新的指针槽位：给槽位赋另一个指针只改变 view，沿槽位中的旧指针修改对象会被两个切片同时看到。若接口承诺“任意修改不会影响内部状态”，这个仅含字符串的 Record 可按值复制到新切片。若以后加上 map 字段，就要重新解释 map 的所有权；若只允许读取，可以提供查询方法。评审时先写清调用方获准修改的层级，再选返回类型。</p><h3 id="injection" tabindex="-1">谁提供依赖、谁负责释放 <a class="header-anchor" href="#injection" aria-label="Permalink to &quot;谁提供依赖、谁负责释放 {#injection}&quot;">​</a></h3><p>文件任务工具让 <code>run</code> 接收 <code>io.Writer</code>，生产入口给它终端，测试传入缓冲区。被测函数负责写入，创建输出目标的一方管理目标的生命周期。这个一方法接口已经能表达需要的能力。<a href="/programming/go/plus/practice/task-cli#test">文件任务工具</a></p>`,39)])])}const g=i(n,[["render",o]]);export{k as __pageData,g as default};
